"""Healthcare AI governance registers derived from the original Cybersecurity Operations Hub."""
def f(label,kind='text',required=False,options=None,ref=None,help=''):
    return dict(label=label,type=kind,required=required,options=options or [],ref=ref,help=help)
REF=lambda label,kind,required=False:f(label,'reference',required,ref=kind)
DATE=lambda label:f(label,'date')
CHOICE=lambda label,values:f(label,'select',options=values.split('|'))

def text(label):return f(label,'textarea',True)
def evidence():return f('Supporting evidence','references',ref='legacy:evidence')
def case():return REF('AI use case','ai_use_case',True)
def yesno(label):return f(label,'select',True,options=['unknown','yes','no'])

